package com.wolfe.admin; import java.util.*; import org.springframework.data.domain.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/admin/staff-alerts") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')") public class StaffAlertController { private final StaffAlertRepository repo; public StaffAlertController(StaffAlertRepository repo){this.repo=repo;} @GetMapping public Page<StaffAlert> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size){return repo.findByAcknowledgedFalseOrderByCreatedAtDesc(PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100)));} @PostMapping("/{id}/ack") public StaffAlert ack(@PathVariable Long id){var a=repo.findById(id).orElseThrow(()->new NoSuchElementException("Staff alert not found"));a.acknowledge();return repo.save(a);} }
